INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch13$PT133-S1-Q1$batch13$, 133, 1, 1, $batch13$Most Strongly Supported$batch13$, $batch13$Backyard gardeners who want to increase the yields of their potato plants should try growing stinging nettles alongside the plants, since stinging nettles attract insects that kill a wide array of insect pests that damage potato plants. It is true that stinging nettles also attract aphids, and that many species of aphids are harmful to potato plants, but that fact in no way contradicts this recommendation, because _______.$batch13$, $batch13$Which one of the following most logically completes the argument?$batch13$, $batch13$C$batch13$, true, $batch13$Batch 13; question text from local bank.$batch13$ FROM lr_sections s WHERE s.preptest=133 AND s.section=1 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$A$batch13$, $batch13$stinging nettles require little care and thus are easy to cultivate$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$A$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$B$batch13$, $batch13$some types of aphids are attracted to stinging nettle plants but do not damage them$batch13$, $batch13$Wrong Target$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$B$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$C$batch13$, $batch13$the types of aphids that stinging nettles attract do not damage potato plants$batch13$, $batch13$Correct$batch13$, true FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$C$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$D$batch13$, $batch13$insect pests typically cause less damage to potato plants than other harmful organisms do$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$D$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch13$E$batch13$, $batch13$most aphid species that are harmful to potato plants cause greater harm to other edible food plants$batch13$, $batch13$Irrelevant$batch13$, false FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch13$E$batch13$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch13$Conclusion$batch13$, $batch13$Gardeners should grow stinging nettles next to their potato plants.$batch13$), (1, $batch13$Evidence$batch13$, $batch13$Nettles attract insects that kill many potato pests.$batch13$), (2, $batch13$Opposing Point$batch13$, $batch13$Nettles also attract aphids, and many aphid species harm potatoes.$batch13$), (3, $batch13$Evaluate$batch13$, $batch13$The blank has to explain why the aphid fact doesn't undercut the recommendation. "Many species of aphids" leaves room: the aphids nettles attract might not be the harmful kinds.$batch13$), (4, $batch13$Goal$batch13$, $batch13$Show that the aphids drawn by nettles don't hurt potatoes.$batch13$)) v(position,label,body) WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch13$A$batch13$, $batch13$Easy care is a nice feature, but it doesn't answer the aphid worry.$batch13$), ($batch13$B$batch13$, $batch13$Whether aphids damage the nettles doesn't matter. The worry is the potatoes.$batch13$), ($batch13$C$batch13$, $batch13$If the aphids nettles attract don't damage potatoes, the aphid fact poses no problem.$batch13$), ($batch13$D$batch13$, $batch13$Comparing pests to other harmful organisms doesn't address aphids.$batch13$), ($batch13$E$batch13$, $batch13$Harming other plants more doesn't mean these aphids leave potatoes alone.$batch13$)) v(letter,body) WHERE q.qid=$batch13$PT133-S1-Q1$batch13$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
